/* Enhanced GT06N Adapter with proper action mapping */
const f = require('../functions');

exports.protocol = 'GT06N';
exports.model_name = 'GT06N';
exports.compatible_hardware = ['GT06N', 'GT06', 'GT06E'];

var adapter = function (device) {
  if (!(this instanceof adapter)) {
    return new adapter(device);
  }

  this.format = {'start': '(', 'end': ')', 'separator': ''};
  this.device = device;
  this.__count = 1;

  this.parse_data = function (data) {
    try {
      var hexData = this.bufferToHexString(data);
      var parts = {
        'raw': hexData,
        'start': hexData.substr(0, 4)
      };

      // Check for valid start bytes
      if (parts['start'] !== '7878' && parts['start'] !== '7979') {
        console.log('Invalid start bytes:', parts['start']);
        parts.cmd = 'noop';
        parts.action = 'noop';
        parts.device_id = '';
        return parts;
      }

      // Parse packet length
      parts['length'] = parseInt(hexData.substr(4, 2), 16);
      
      // Check if we have enough data
      const expectedLength = 8 + parts['length'] * 2 + 4; // start(4) + len(2) + proto(2) + data + crc(2) + stop(2)
      if (hexData.length < expectedLength) {
        console.log('Incomplete packet, waiting for more data');
        parts.cmd = 'noop';
        parts.action = 'noop';
        parts.device_id = '';
        return parts;
      }

      parts['protocol_id'] = hexData.substr(6, 2);
      parts['information'] = hexData.substr(8, parts['length'] * 2 - 2); // -2 for protocol_id
      
      // Extract CRC (2 bytes before stop bytes)
      parts['crc'] = hexData.substr(8 + parts['length'] * 2 - 4, 2);
      
      // Extract stop bytes (last 4 hex chars)
      parts['stop'] = hexData.substr(hexData.length - 4, 4);

      // Map protocol IDs to actions
      switch(parts['protocol_id']) {
        case '01': // Login packet
          parts['device_id'] = parts['information'].substr(0, 16);
          parts.cmd = 'login_request';
          parts.action = 'login_request';
          break;
          
        case '12': // Location data
        case '22': // GPS with address
          parts['data'] = parts['information'];
          parts.cmd = 'location';
          parts.action = 'location';
          break;
          
        case '13': // Heartbeat
          parts.cmd = 'heartbeat';
          parts.action = 'heartbeat';
          break;
          
        case '16': // Alarm data
        case '26': // Alarm with address
          parts['data'] = parts['information'];
          parts.cmd = 'alarm';
          parts.action = 'alarm';
          break;
          
        case '17': // LBS location
          parts['data'] = parts['information'];
          parts.cmd = 'lbs_location';
          parts.action = 'lbs_location';
          break;
          
        case '18': // Status information
          parts['status_data'] = parts['information'];
          parts.cmd = 'status';
          parts.action = 'status';
          break;
          
        default:
          parts.cmd = 'noop';
          parts.action = 'noop';
          console.log('Unknown protocol:', parts['protocol_id']);
      }

      // Ensure device_id is always set
      if (!parts['device_id']) {
        parts['device_id'] = '';
      }

      console.log(`Parsed packet: Protocol=${parts['protocol_id']}, Action=${parts.action}, DeviceID=${parts.device_id}`);
      return parts;
    } catch (error) {
      console.error('Error parsing data:', error);
      return {
        cmd: 'noop',
        action: 'noop',
        device_id: ''
      };
    }
  };

  this.bufferToHexString = function (buffer) {
    var str = '';
    for (var i = 0; i < buffer.length; i++) {
      var hex = buffer[i].toString(16);
      str += hex.length === 1 ? '0' + hex : hex;
    }
    return str;
  };

  this.authorize = function () {
    var length = '05';
    var protocol_id = '01';
    var serial = f.str_pad(this.__count, 4, 0);
    var str = length + protocol_id + serial;
    this.__count++;
    
    var crc = require('crc');
    var crcResult = f.str_pad(crc.crc16(str).toString(16), 4, '0').substr(2, 2);
    
    // Response: 7878 05 01 [serial] [crc] 0d0a
    var response = '7878' + length + protocol_id + serial + crcResult + '0d0a';
    console.log('Sending login response:', response);
    this.device.send(Buffer.from(response, 'hex'));
  };
  
  this.receive_heartbeat = function (msg_parts) {
    var serial = msg_parts.serial_number || '0001';
    var response = '78780513' + serial + '00000d0a';
    console.log('Sending heartbeat response:', response);
    this.device.send(Buffer.from(response, 'hex'));
  };

  this.receive_location = function (msg_parts) {
    var serial = msg_parts.serial_number || '0001';
    var response = '78780512' + serial + '00000d0a';
    console.log('Sending location response:', response);
    this.device.send(Buffer.from(response, 'hex'));
  };

  this.receive_alarm = function (msg_parts) {
    var str = msg_parts.data;
    
    // Enhanced alarm parsing
    var data = {
      'date': str.substr(0, 12),
      'satellites': parseInt(str.substr(12, 2), 16),
      'latitude_raw': str.substr(14, 8),
      'longitude_raw': str.substr(22, 8),
      'latitude': this.hexToDecimalDegrees(str.substr(14, 8)),
      'longitude': this.hexToDecimalDegrees(str.substr(22, 8)),
      'speed': parseInt(str.substr(30, 2), 16),
      'course': parseInt(str.substr(32, 4), 16),
      'timestamp': new Date(),
      'device_status': f.str_pad(parseInt(str.substr(36, 2), 16).toString(2), 8, 0),
      'lbs': str.substr(38, 16),
      'alarm_type': this.getAlarmType(str.substr(54, 2) || '01'),
      'alarm_code': str.substr(54, 2) || '01',
      'language': str.substr(56, 2),
      'raw_data': str
    };
    
    // Parse status bits
    if (data['device_status']) {
      data['power_status'] = data['device_status'][0]; // 0: normal, 1: low
      data['gps_status'] = data['device_status'][1];   // 0: valid, 1: invalid
      data['charge_status'] = data['device_status'][5]; // 0: not charging, 1: charging
      data['acc_status'] = data['device_status'][6];   // 0: off, 1: on
      data['armed_status'] = data['device_status'][7]; // 0: disarmed, 1: armed
    }
    
    // Convert to boolean values for API
    data['device_status_bool'] = {
      power: data['power_status'] === '0' ? 'normal' : 'low',
      charging: data['charge_status'] === '1',
      acc: data['acc_status'] === '1',
      armed: data['armed_status'] === '1'
    };
    
    return {
      code: data.alarm_type,
      msg: data.alarm_type,
      device_id: msg_parts.device_id || '',
      ...data,
      device_status: data['device_status_bool']
    };
  };

  this.get_location_data = function (msg_parts) {
    var str = msg_parts.data;
    
    var data = {
      'date': str.substr(0, 12),
      'satellites': parseInt(str.substr(12, 2), 16),
      'latitude_raw': str.substr(14, 8),
      'longitude_raw': str.substr(22, 8),
      'latitude': this.hexToDecimalDegrees(str.substr(14, 8)),
      'longitude': this.hexToDecimalDegrees(str.substr(22, 8)),
      'speed': parseInt(str.substr(30, 2), 16),
      'course': parseInt(str.substr(32, 4), 16),
      'device_status': f.str_pad(parseInt(str.substr(36, 2), 16).toString(2), 8, 0),
      'lbs': str.substr(38, 16),
      'raw_data': str
    };
    
    // Parse status bits
    if (data['device_status']) {
      data['power_status'] = data['device_status'][0];
      data['gps_status'] = data['device_status'][1];
      data['charge_status'] = data['device_status'][5];
      data['acc_status'] = data['device_status'][6];
      data['armed_status'] = data['device_status'][7];
    }
    
    // Convert to boolean values for API
    data['device_status_bool'] = {
      power: data['power_status'] === '0' ? 'normal' : 'low',
      charging: data['charge_status'] === '1',
      acc: data['acc_status'] === '1',
      armed: data['armed_status'] === '1'
    };
    
    return {
      device_id: msg_parts.device_id || '',
      date: data.date,
      latitude: data.latitude,
      longitude: data.longitude,
      speed: data.speed,
      orientation: data.course,
      satellites: data.satellites,
      device_status: data['device_status_bool'],
      raw_data: data.raw_data
    };
  };

  this.hexToDecimalDegrees = function (hex) {
    var decimal = parseInt(hex, 16);
    return decimal / 1800000;
  };

  this.getAlarmType = function (hexCode) {
    var codes = {
      '01': 'SOS',
      '02': 'Low Battery',
      '03': 'Power Cut',
      '04': 'Shock',
      '05': 'Fence In',
      '06': 'Fence Out',
      '09': 'Over Speed',
      '10': 'Movement',
      '12': 'Enter Area',
      '13': 'Exit Area',
      '15': 'Power On',
      '16': 'GPS First Fix',
      '17': 'GPS Antenna Short',
      '18': 'GPS Antenna Open',
      '19': 'Power Off',
      '20': 'Sleep Mode',
      '21': 'Wake Up',
      '22': 'Door Open',
      '23': 'Door Close',
      '46': 'Temperature Alarm',  // Added based on your logs
      '50': 'Vibration Alarm'     // Added based on your logs
    };
    
    return codes[hexCode] || `Unknown Alarm: ${hexCode}`;
  };

  // Handle 'ping' action (backwards compatibility)
  this.get_ping_data = function (msg_parts) {
    return this.get_location_data(msg_parts);
  };

  this.request_login_to_device = function () {
    // Not implemented
  };

  this.run_other = function (cmd, msg_parts) {
    console.log('run_other called with cmd:', cmd);
  };

  this.set_refresh_time = function (interval, duration) {
    // Not implemented
  };
};

exports.adapter = adapter;